import { Settings, Moon, Sun } from 'lucide-react';
import { Button } from './ui/button';

const TopNavigation = ({ darkMode, setDarkMode }) => {
  return (
    <nav className="top-navigation">
      <div className="top-nav-content">
        <div className="top-nav-left">
          <Button variant="ghost" size="icon" className="nav-icon-button">
            <Settings className="w-5 h-5" />
          </Button>
        </div>

        <div className="top-nav-center">
          <a href="#" className="nav-link">Search for Jobs</a>
          <a href="#" className="nav-link">Candidate Home</a>
          <a href="#" className="nav-link">Job Alerts</a>
        </div>

        <div className="top-nav-right">
          <Button 
            variant="ghost" 
            size="icon" 
            className="nav-icon-button"
            onClick={() => setDarkMode(!darkMode)}
          >
            {darkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
          </Button>
          <span className="nav-email">yaswanthkumarchekuri@gmail.com</span>
        </div>
      </div>

      <style jsx="true">{`
        .top-navigation {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          background-color: var(--workday-card);
          border-bottom: 1px solid var(--workday-border);
          z-index: 1000;
          height: 60px;
        }

        .top-nav-content {
          max-width: 1400px;
          margin: 0 auto;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: space-between;
          padding: 0 5px;
        }

        .top-nav-left,
        .top-nav-right {
          display: flex;
          align-items: center;
          gap: 5px;
        }

        .top-nav-center {
          display: flex;
          align-items: center;
          gap: 32px;
        }

        .nav-link {
          color: var(--workday-text);
          text-decoration: none;
          font-size: 14px;
          font-weight: 500;
          transition: color 0.2s;
        }

        .nav-link:hover {
          color: var(--workday-primary);
        }

        .nav-email {
          color: var(--workday-text-light);
          font-size: 14px;
        }

        .nav-icon-button {
          color: var(--workday-text);
        }

        @media (max-width: 768px) {
          .top-nav-center {
            display: none;
          }

          .nav-email {
            display: none;
          }
        }
      `}</style>
    </nav>
  );
};

export default TopNavigation;
